var seed = 12345;
function rnd() { seed = (seed + 0x6D2B79F5) | 0; var t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
var N = 14, T = 14, SIG = 1.0, XR = 2.4;
var tr = [];
for (var i = 0; i < N; i++) {
  var p = (i + 0.5) / N;
  var z = 4.91 * (Math.pow(p, 0.14) - Math.pow(1 - p, 0.14));
  var x0 = SIG * z + (rnd() - 0.5) * 0.12;
  tr.push({ x0: x0, m: x0 < 0 ? -1 : 1, q: 2.6 + 0.8 * rnd(), a: rnd() * 2 - 1 });
}
function pos(o, t, kind) {
  if (kind === 0) return o.m + (o.x0 - o.m) * (1 - Math.pow(1 - t, o.q));
  return o.m + (o.x0 - o.m) * t + o.a * 0.07 * Math.sin(Math.PI * t);
}
function vel(o, t, kind) {
  if (kind === 0) return (o.x0 - o.m) * o.q * Math.pow(1 - t, o.q - 1);
  return (o.x0 - o.m) + o.a * 0.07 * Math.PI * Math.cos(Math.PI * t);
}
var E = [[], []], err = [0, 0];
for (var k = 0; k < 2; k++) {
  var s = 0;
  for (var i = 0; i < N; i++) {
    var xs = [tr[i].x0];
    for (var j = 0; j < 4; j++) xs.push(xs[j] - 0.25 * vel(tr[i], 1 - 0.25 * j, k));
    E[k].push(xs);
    s += Math.abs(xs[4] - tr[i].m);
  }
  err[k] = s / N;
}
function cl(x) { return Math.max(0, Math.min(1, x)); }
function sm(x) { x = cl(x); return x * x * (3 - 2 * x); }
var INK = '#04204B', SEC = '#3D5F91', GUIDE = '#8098BC', WARM = '#B4552F', BLUE = '#0B4FC0', TEAL = '#138374';
var caps = [
  [0, 'Start: noise samples x(1) ~ N(0, σ²)'],
  [1.2, 'Integrate dx/dt = v(x,t) from t=1 to t=0'],
  [6.2, 'Exact paths end at the two modes x = ±1'],
  [7.4, 'Euler with 4 large steps (h = 0.25)'],
  [11.7, 'straighter paths need fewer steps']
];

function draw(ctx, W, H, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, W, H);
  var tm = time % T;
  var ga = Math.min(sm(tm / 0.6), 1 - sm((tm - 13.4) / 0.6));
  // caption
  var ci = 0;
  for (var c = 0; c < caps.length; c++) if (tm >= caps[c][0]) ci = c;
  var cs = caps[ci][0], ce = ci + 1 < caps.length ? caps[ci + 1][0] : T;
  var ca = Math.min(sm((tm - cs) / 0.3), 1 - sm((tm - (ce - 0.3)) / 0.3));
  ctx.globalAlpha = Math.max(0, ca);
  ctx.fillStyle = INK;
  ctx.font = 'bold 13px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.fillText(caps[ci][1], W / 2, 20);
  ctx.globalAlpha = 1;

  var wide = W >= 600;
  var P = [];
  for (var k = 0; k < 2; k++) {
    if (wide) {
      var pw = (W - 24 - 16) / 2;
      P.push({ x: 12 + k * (pw + 16), w: pw, ty: 52, pt: 66, pb: H - 58, ly: H - 44, my: H - 20 });
    } else {
      var bh = (H - 36) / 2, top = 34 + k * bh;
      P.push({ x: 12, w: W - 24, ty: top + 12, pt: top + 20, pb: top + bh - 34, ly: top + bh - 21, my: top + bh - 7 });
    }
  }
  var titles = ['curved paths (diffusion ODE)', 'straight paths (rectified flow)'];
  var cols = [WARM, BLUE];

  // global time quantities
  var inInt = tm >= 1.2 && tm < 6.2;
  var s1 = sm((tm - 1.2) / 5.0);
  var u = cl((tm - 7.6) / 4.0) * 4;
  var eul = tm >= 7.4 && tm < T;
  var ej = Math.min(3, Math.floor(u));
  var ef = sm(u - ej);
  var ett = 1 - 0.25 * ej - 0.25 * ef;
  var tc = inInt ? 1 - s1 : (tm >= 6.2 && tm < 7.4 ? 0 : (eul ? ett : 1));
  var showCur = inInt || (eul && tm >= 7.6);
  var trA = tm < 6.2 ? 0.55 : 0.55 - 0.3 * sm((tm - 7.0) / 0.5);
  var dotA = tm < 7.0 ? 1 : 1 - sm((tm - 7.0) / 0.4);
  var ovA = eul ? sm((tm - 7.2) / 0.4) : 0;

  for (var k = 0; k < 2; k++) {
    var Q = P[k];
    var PL = Q.x + 32, PR = Q.x + Q.w - 10;
    var ph = Q.pb - Q.pt, cy = (Q.pt + Q.pb) / 2, sc = ph / (2 * XR);
    var bw = Math.min(40, Q.w * 0.12);
    var px = function (t) { return PR - t * (PR - PL); };
    var py = function (x) { return cy - x * sc; };
    ctx.globalAlpha = ga;
    ctx.textAlign = 'center';
    ctx.fillStyle = INK;
    ctx.font = 'bold 13px sans-serif';
    ctx.fillText(titles[k], Q.x + Q.w / 2, Q.ty);
    // guides
    ctx.strokeStyle = GUIDE; ctx.lineWidth = 1;
    ctx.setLineDash([3, 4]);
    for (var g = -1; g <= 1; g += 2) { ctx.beginPath(); ctx.moveTo(PL, py(g)); ctx.lineTo(PR, py(g)); ctx.stroke(); }
    ctx.setLineDash([]);
    // axes
    ctx.strokeStyle = GUIDE;
    ctx.beginPath(); ctx.moveTo(PL, Q.pb); ctx.lineTo(PR, Q.pb); ctx.moveTo(PL, Q.pt); ctx.lineTo(PL, Q.pb); ctx.stroke();
    for (var q = 0; q <= 4; q++) { var tx = px(1 - 0.25 * q); ctx.beginPath(); ctx.moveTo(tx, Q.pb); ctx.lineTo(tx, Q.pb + 4); ctx.stroke(); }
    ctx.fillStyle = SEC; ctx.font = '11px sans-serif'; ctx.textAlign = 'right';
    ctx.fillText('+1', PL - 6, py(1) + 4); ctx.fillText('0', PL - 6, py(0) + 4); ctx.fillText('−1', PL - 6, py(-1) + 4);
    ctx.textAlign = 'left'; ctx.fillText('x', Q.x + 2, Q.pt + 4);
    ctx.textAlign = 'left'; ctx.fillText('t=1 noise', PL, Q.ly);
    ctx.textAlign = 'right'; ctx.fillText('t=0 data', PR, Q.ly);
    // density profiles
    ctx.strokeStyle = SEC; ctx.lineWidth = 1.2;
    ctx.beginPath();
    for (var x = -XR; x <= XR + 1e-6; x += 0.1) { var X = PL + bw * Math.exp(-x * x / (2 * SIG * SIG)), Y = py(x); if (x === -XR) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
    ctx.stroke();
    ctx.beginPath();
    for (var x = -XR; x <= XR + 1e-6; x += 0.03) { var d1 = (x - 1) / 0.07, d2 = (x + 1) / 0.07; var X = PR - bw * (Math.exp(-d1 * d1 / 2) + Math.exp(-d2 * d2 / 2)), Y = py(x); if (x === -XR) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
    ctx.stroke();
    // Euler step guides
    if (ovA > 0) {
      ctx.globalAlpha = ga * ovA * 0.5; ctx.strokeStyle = GUIDE; ctx.setLineDash([2, 4]);
      for (var q = 1; q <= 3; q++) { var tx = px(1 - 0.25 * q); ctx.beginPath(); ctx.moveTo(tx, Q.pt); ctx.lineTo(tx, Q.pb); ctx.stroke(); }
      ctx.setLineDash([]);
    }
    // exact trajectories
    var tEnd = tm < 1.2 ? 1 : (inInt ? 1 - s1 : 0);
    ctx.globalAlpha = ga * trA; ctx.strokeStyle = cols[k]; ctx.lineWidth = 1.3;
    if (tEnd < 1) {
      for (var i = 0; i < N; i++) {
        var n = Math.max(2, Math.ceil(40 * (1 - tEnd)));
        ctx.beginPath();
        for (var j = 0; j <= n; j++) { var t = 1 - (1 - tEnd) * j / n; var X = px(t), Y = py(pos(tr[i], t, k)); if (j === 0) ctx.moveTo(X, Y); else ctx.lineTo(X, Y); }
        ctx.stroke();
      }
    }
    // exact dots
    if (dotA > 0) {
      ctx.globalAlpha = ga * dotA; ctx.fillStyle = cols[k];
      for (var i = 0; i < N; i++) { ctx.beginPath(); ctx.arc(px(tEnd), py(pos(tr[i], tEnd, k)), 3.2, 0, 6.2832); ctx.fill(); }
    }
    // cursor
    if (showCur) {
      ctx.globalAlpha = ga * 0.6; ctx.strokeStyle = GUIDE; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(px(tc), Q.pt); ctx.lineTo(px(tc), Q.pb); ctx.stroke();
    }
    // Euler overlay
    if (ovA > 0) {
      ctx.globalAlpha = ga * ovA;
      var fin = tm >= 11.6;
      for (var i = 0; i < N; i++) {
        var xs = E[k][i];
        ctx.strokeStyle = TEAL; ctx.lineWidth = 1.6;
        ctx.beginPath(); ctx.moveTo(px(1), py(xs[0]));
        var hx = xs[0], ht = 1;
        if (tm >= 7.6) {
          for (var j = 1; j <= ej; j++) ctx.lineTo(px(1 - 0.25 * j), py(xs[j]));
          hx = xs[ej] + (xs[ej + 1] - xs[ej]) * ef; ht = ett;
          ctx.lineTo(px(ht), py(hx));
        }
        ctx.stroke();
        ctx.fillStyle = '#ffffff'; ctx.lineWidth = 1.2;
        if (tm >= 7.6) for (var j = 0; j <= ej; j++) { ctx.beginPath(); ctx.arc(px(1 - 0.25 * j), py(xs[j]), 2.2, 0, 6.2832); ctx.fill(); ctx.stroke(); }
        ctx.fillStyle = TEAL; ctx.beginPath(); ctx.arc(px(ht), py(hx), 3.6, 0, 6.2832); ctx.fill();
        if (fin) {
          ctx.globalAlpha = ga * ovA * sm((tm - 11.6) / 0.5) * 0.7;
          ctx.strokeStyle = INK; ctx.lineWidth = 1; ctx.setLineDash([2, 2]);
          ctx.beginPath(); ctx.moveTo(PR, py(xs[4])); ctx.lineTo(PR, py(tr[i].m)); ctx.stroke();
          ctx.setLineDash([]);
          ctx.globalAlpha = ga * ovA;
        }
      }
    }
    // labels at bottom
    ctx.globalAlpha = ga;
    ctx.fillStyle = INK; ctx.font = '11px sans-serif'; ctx.textAlign = 'center';
    var lab = '';
    if (inInt) lab = 't = ' + tc.toFixed(2);
    else if (eul && tm >= 7.6) lab = 't = ' + tc.toFixed(2) + ' (step ' + Math.min(4, Math.floor(u) + 1) + '/4)';
    if (lab) ctx.fillText(lab, (PL + PR) / 2, Q.ly);
    if (tm >= 11.6) {
      ctx.globalAlpha = ga * sm((tm - 11.6) / 0.5);
      ctx.fillStyle = cols[k]; ctx.font = 'bold 12px sans-serif';
      ctx.fillText('4-step mean miss: ' + err[k].toFixed(2), Q.x + Q.w / 2, Q.my);
    }
    ctx.globalAlpha = 1;
  }
  ctx.globalAlpha = 1;
}
return { draw: draw };
